// App.js
import React, { useState, useEffect, useCallback } from 'react';
import './App.css';

// --- MOCK DATA & SIMULATION CONSTANTS ---
const MOCK_REST_ENDPOINT = '/api/v1/search_records';
const MOCK_WS_URL = 'ws://api.corp.net/realtime_feed';

const initialData = [
    { id: 'REC-4901', type: 'Audit Log', status: 'ACTIVE', timestamp: '2024-07-20T10:00:00Z', owner: 'J. Doe' },
    { id: 'REC-4902', type: 'Transaction Batch', status: 'PENDING', timestamp: '2024-07-20T10:05:00Z', owner: 'S. Chen' },
    { id: 'REC-4903', type: 'System Health Report', status: 'ACTIVE', timestamp: '2024-07-20T10:15:00Z', owner: 'System' },
];

function App() {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [realTimeData, setRealTimeData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [wsConnected, setWsConnected] = useState(false);

  // --- 1. WebSocket Simulation ---
  useEffect(() => {
    console.log(`Attempting connection to ${MOCK_WS_URL}...`);

    // Simulate WebSocket connection lifecycle
    const connectionTimer = setTimeout(() => {
        setWsConnected(true);
        console.log("WS: Connection established.");

        // Simulate incoming messages
        const messageInterval = setInterval(() => {
            const newRecord = {
                id: `RT-${Date.now() % 10000}`,
                type: 'Real-Time Alert',
                status: Math.random() > 0.8 ? 'ERROR' : 'ACTIVE',
                timestamp: new Date().toISOString(),
                owner: 'Automated Monitor',
            };
            setRealTimeData(prev => [newRecord, ...prev].slice(0, 10)); // Keep last 10 updates
            console.log(`WS: New data received: ${newRecord.id}`);
        }, 5000); // New update every 5 seconds

        return () => {
            clearInterval(messageInterval);
            setWsConnected(false);
            console.log("WS: Connection closed.");
        };
    }, 1000); // Connection takes 1 second to establish

    return () => clearTimeout(connectionTimer);
  }, []);


  // --- 2. REST API Search Simulation ---
  const handleSearch = useCallback(async () => {
    if (!searchTerm.trim()) {
        setError("Validation Error: Search parameter is empty.");
        setSearchResults([]);
        return;
    }

    setLoading(true);
    setError(null);
    setSearchResults([]);

    try {
      // Simulate API call delay
      await new Promise(resolve => setTimeout(resolve, 1000)); 

      // Filter mock data based on search term (case-insensitive)
      const filtered = initialData.filter(item => 
        item.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.type.toLowerCase().includes(searchTerm.toLowerCase())
      );

      if (filtered.length === 0) {
          setError(`No records found matching query: "${searchTerm}"`);
      } else {
        setSearchResults(filtered);
      }

    } catch (err) {
      console.error("API Error:", err);
      setError("Network Timeout: Could not reach the primary database server.");
    } finally {
      setLoading(false);
    }
  }, [searchTerm]);

  // Helper function to get status color class
  const getStatusClass = (status) => {
    switch (status) {
        case 'ACTIVE': return 'ACTIVE';
        case 'PENDING': return 'PENDING';
        case 'ERROR': return 'ERROR';
        default: return '';
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Enterprise Data Retrieval Portal</h1>
        <p>Secure access to operational records via REST and Real-Time Streaming.</p>
      </header>

      {/* Status Bar */}
      <div className="status-bar">
        <span className={`status-indicator ${wsConnected ? 'CONNECTED' : 'DISCONNECTED'}`}></span>
        Real-Time Feed Status: {wsConnected ? 'Connected to Data Stream' : 'Attempting Connection...'}
      </div>


      {/* Search Interface (REST API Interaction) */}
      <div className="search-container">
        <input
          type="text"
          className="search-input"
          placeholder="Enter Record ID or Type to query primary database..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          onKeyPress={(e) => {
            if (e.key === 'Enter' && !loading) {
              handleSearch();
            }
          }}
          disabled={loading}
        />
        <button className="search-button" onClick={handleSearch} disabled={loading}>
          {loading ? 'PROCESSING...' : 'QUERY DATABASE'}
        </button>
      </div>

      {error && <div className={`feedback-message ${error.includes('Error') || error.includes('Timeout') ? 'error' : ''}`}>{error}</div>}

      {/* Search Results (REST API Output) */}
      {searchResults.length > 0 && (
        <section className="results-section">
            <h2 className="results-header">Query Results ({searchResults.length} Matches)</h2>
            <div className="results-grid">
                {searchResults.map((item) => (
                <div key={item.id} className="data-entry">
                    <h3>ID: {item.id}</h3>
                    <p>Owner: {item.owner}</p>
                    <p>Type: {item.type}</p>
                    <span className={`status-tag ${getStatusClass(item.status)}`}>{item.status}</span>
                </div>
                ))}
            </div>
        </section>
      )}

      {/* Real-Time Feed (WebSocket Output) */}
      <section className="results-section">
        <h2 className="results-header">Live Data Stream Feed (Last 10 Events)</h2>
        <div className="results-grid">
            {realTimeData.length > 0 ? (
                realTimeData.map((item) => (
                <div key={item.id} className="data-entry">
                    <h3>{item.type}</h3>
                    <p>Source ID: {item.id}</p>
                    <p>Last Update: {new Date(item.timestamp).toLocaleTimeString()}</p>
                    <span className={`status-tag ${getStatusClass(item.status)}`}>{item.status}</span>
                </div>
                ))
            ) : (
                <div className="feedback-message">Waiting for initial data packets from the streaming server...</div>
            )}
        </div>
      </section>

    </div>
  );
}

export default App;
